const invoices = $('Read Invoices from Sheets').all().map(x => x.json);
const workItems = $('Read Work Delivered from Sheets').all().map(x => x.json);
const payments = $('Read Payments from Sheets').all().map(x => x.json);
const followUps = $('Read Follow-ups from Sheets').all().map(x => x.json);
const cfg = $('Set Configuration Parameters').first().json;
const asOf = new Date();
const dateOnly = d => new Date(d.getFullYear(), d.getMonth(), d.getDate());
const daysBetween = (a,b) => Math.floor((dateOnly(a)-dateOnly(b))/86400000);
const num = v => Number(String(v ?? 0).replace(/[,₹\s]/g,'')) || 0;
const byInvoice = new Map(invoices.map(i => [String(i.Invoice_ID || '').trim(), i]).filter(([k])=>k));
const paymentsByInvoice = {};
for (const p of payments) {
  const k=String(p.Invoice_ID || '').trim();
  if(k) paymentsByInvoice[k]=(paymentsByInvoice[k]||0)+num(p.Amount_Paid);
}
const invoicesByWork = {};
for (const inv of invoices) {
  const k=String(inv.Work_ID || '').trim();
  if(k) (invoicesByWork[k] ||= []).push(inv);
}
const followupsByInvoice = {};
for (const f of followUps) {
  const k=String(f.Invoice_ID || '').trim();
  if(k) (followupsByInvoice[k] ||= []).push(f);
}
const findings=[];
function add(type, subtype, ref, client, clientId, amount, days, audience, description, extra={}) {
  findings.push({finding_type:type,subtype,reference_id:String(ref||'UNKNOWN'),client_name:client||'Unknown client',
    client_id:clientId||'UNKNOWN',client_email:extra.client_email||'',amount_at_risk:Math.max(0,num(amount)),
    days:Number(days)||0,audience,description,recommended_tone:extra.recommended_tone||'Professional Internal'});
}
for (const w of workItems) {
  if (!['Accepted','Delivered'].includes(String(w.Status||'').trim())) continue;
  const age = w.Delivered_Date ? daysBetween(asOf,new Date(w.Delivered_Date)) : 0;
  const wid=String(w.Work_ID||'').trim(), iid=String(w.Invoice_ID||'').trim();
  if (!iid && age > Number(cfg.gracePeriodDays||7)) {
    add('UNINVOICED_WORK','NO_INVOICE',wid,w.Client_Name,w.Client_ID,w.Agreed_Amount,age,'INTERNAL',`Accepted or delivered work has no invoice after ${age} days`);
  } else if (iid && !byInvoice.has(iid)) {
    add('UNINVOICED_WORK','INVOICE_REF_MISSING',wid,w.Client_Name,w.Client_ID,w.Agreed_Amount,age,'INTERNAL',`Work references missing invoice ${iid}`);
  }
  const linked=invoicesByWork[wid]||[];
  if(linked.length>1) add('DUPLICATE_BILLING','MULTIPLE_INVOICES',wid,w.Client_Name,w.Client_ID,w.Agreed_Amount,0,'INTERNAL',`Multiple invoices reference work ${wid}: ${linked.map(x=>x.Invoice_ID).join(', ')}`);
  else if(linked.length===1) {
    const diff=num(linked[0].Invoice_Amount)-num(w.Agreed_Amount);
    if(diff<0) add('BILLING_VARIANCE','UNDER_BILLED',wid,w.Client_Name,w.Client_ID,Math.abs(diff),0,'INTERNAL',`Agreed amount ${num(w.Agreed_Amount)} but invoiced ${num(linked[0].Invoice_Amount)}`);
    if(diff>0) add('BILLING_VARIANCE','OVER_BILLED',wid,w.Client_Name,w.Client_ID,diff,0,'INTERNAL',`Invoice ${linked[0].Invoice_ID} exceeds the agreed amount by ${diff}`);
  }
}
for(const inv of invoices) {
  const id=String(inv.Invoice_ID||'').trim();
  const issue=inv.Issue_Date ? new Date(inv.Issue_Date) : null;
  if(inv.Status==='Draft' && issue) {
    const age=daysBetween(asOf,issue);
    if(age>Number(cfg.draftThresholdDays||3)) add('DRAFT_NOT_SENT','DRAFT_INVOICE',id,inv.Client_Name,inv.Client_ID,inv.Invoice_Amount,age,'INTERNAL',`Draft invoice has not been dispatched for ${age} days`);
  }
  const paid=paymentsByInvoice[id]||0, balance=num(inv.Invoice_Amount)-paid, recorded=num(inv.Recorded_Balance);
  if(inv.Status!=='Draft' && Math.abs(balance-recorded)>0.01) {
    let subtype='PAYMENT_NOT_POSTED';
    if(Math.abs(balance)<0.01 && recorded>0) subtype='PAID_BUT_OPEN';
    else if(balance<0) subtype='OVERPAID';
    else if(recorded===0 && balance>0) subtype='BALANCE_UNDERSTATED';
    add('BALANCE_MISMATCH',subtype,id,inv.Client_Name,inv.Client_ID,Math.abs(recorded-balance),0,'INTERNAL',`Recorded balance ${recorded} differs from calculated balance ${balance}`);
  }
  if(balance>0 && inv.Due_Date && inv.Status!=='Draft') {
    const due=new Date(inv.Due_Date), overdue=daysBetween(asOf,due), untilDue=daysBetween(due,asOf);
    const fus=(followupsByInvoice[id]||[]).slice().sort((a,b)=>new Date(b.Followup_Date||0)-new Date(a.Followup_Date||0));
    if(overdue>0) {
      const last=fus[0], stale=!last || (last.Next_Action_Date && dateOnly(new Date(last.Next_Action_Date))<dateOnly(asOf)) ||
        (!last.Next_Action_Date && daysBetween(asOf,new Date(last.Followup_Date||0))>Number(cfg.staleFollowupDays||14));
      if(stale) add('OVERDUE_NO_FOLLOWUP',last?'STALE_FOLLOWUP':'NO_FOLLOWUP_EVER',id,inv.Client_Name,inv.Client_ID,balance,overdue,'CUSTOMER',`Invoice is overdue by ${overdue} days with outstanding balance ${balance}`,{client_email:inv.Client_Email,recommended_tone:overdue>=30?'FINAL_ESCALATION':overdue>=15?'FIRM_REMINDER':'FRIENDLY_REMINDER'});
    } else if(untilDue>=0 && untilDue<=Number(cfg.dueSoonDays||3) && fus.length===0) {
      add('DUE_SOON','DUE_IN_3_DAYS',id,inv.Client_Name,inv.Client_ID,balance,untilDue,'CUSTOMER',`Invoice is due in ${untilDue} days with outstanding balance ${balance}`,{client_email:inv.Client_Email,recommended_tone:'FRIENDLY_HEADS_UP'});
    }
  }
}
for(const p of payments) {
  const id=String(p.Invoice_ID||'').trim();
  if(id && !byInvoice.has(id)) add('ORPHAN_PAYMENT','INVOICE_NOT_FOUND',id,'Unknown payer','UNKNOWN',p.Amount_Paid,0,'INTERNAL',`Payment ${p.Payment_ID||''} references missing invoice ${id}`);
}
for(const f of findings) {
  f.priority=(f.amount_at_risk>=100000||f.days>=30)?'HIGH':(f.amount_at_risk>=50000||f.days>=15||f.finding_type==='DUPLICATE_BILLING')?'MEDIUM':'LOW';
  f.Followup_ID=`REC-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
  f.Invoice_ID=String(f.reference_id).startsWith('INV-')?f.reference_id:'';
  f.Work_ID=String(f.reference_id).startsWith('W-')?f.reference_id:'';
  f.Followup_Date=asOf.toISOString().slice(0,10);
  f.Channel=f.audience==='CUSTOMER'?'Email':'Internal Ops';
  f.Outcome=`System identified: ${f.description}`;
  f.Next_Action_Date=new Date(asOf.getTime()+(f.priority==='HIGH'?86400000:259200000)).toISOString().slice(0,10);
  f.Owner='Finance Ops Lead'; f.Source='Automated Leakage Audit'; f.Finding_Type=f.finding_type;
  f.Priority=f.priority; f.Amount_At_Risk=f.amount_at_risk; f.Status='Open';
}
return findings.map(f=>({json:f}));

return $input.all().map((item) => {
  const f = item.json;
  const promptText = `Act as a B2B finance operations specialist in India. Draft a message for this finding.
Audience: ${f.audience}
Client: ${f.client_name}
Finding: ${f.finding_type} / ${f.subtype}
Reference: ${f.reference_id}
Amount at risk in INR: ${f.amount_at_risk}
Days: ${f.days}
Tone: ${f.recommended_tone}
Context: ${f.description}

Return only valid JSON with exactly these keys:
{"audience":"CUSTOMER or INTERNAL","subject":"short subject","message_body":"message text","recommended_action":"specific next step"}
Do not invent facts, payment links, invoice details, or commitments. Do not send the message yourself.`;
  return {json:{...f,promptText}};
});

const raw = String($json.output ?? $json.text ?? '');
let parsed;
try {
  const cleaned=raw.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();
  const match=cleaned.match(/\{[\s\S]*\}/);
  if(!match) throw new Error('No JSON object in model output');
  parsed=JSON.parse(match[0]);
} catch(e) {
  parsed={subject:'Finance operations review required',message_body:'',recommended_action:'Review the finding manually',parse_error:e.message};
}
const source = $('Create AI Dispatch Prompts').item.json;
return [{json:{...source,aiSubject:parsed.subject||'Finance Operations Update',aiMessage:parsed.message_body||'',aiAction:parsed.recommended_action||'Review finding manually',aiParseError:parsed.parse_error||''}}];
